# font-size:13px;line-height:1.8}
#label.plan:has(input:checked){border-color:var(--btn)}
#label.plan input{width:auto;margin:5px 0 0;accent-color:var(--btn)}
#label.plan .p{font-weight:600}
#label.plan small{color:var(--muted)}
#label.plan small.games{color:var(--dim);line-height:2}
#.dns input[type=file]{width:100%;padding:10px;font-size:12px;
# border:1px dashed var(--line2);background:transparent;margin-bottom:4px}
#details.pw{margin-top:16px;border:1px solid var(--line);border-radius:12px;
# background:var(--bg)}
#details.pw>summary{padding:14px 16px;cursor:pointer;color:var(--dim);font-size:13px;
# list-style:none}
#details.pw>summary::-webkit-details-marker{display:none}
#details.pw>summary::before{content:'▸';margin-left:8px;font-size:11px}
#details.pw[open]>summary::before{content:'▾'}
#details.pw form{padding:0 16px 4px}
#details.pw .note{padding:0 16px 14px;margin-top:8px}
#details.pw h3{font-size:13px;margin:18px 16px 6px;color:var(--fg)}
#details.pw>.btn{margin:0 16px;width:calc(100% - 32px)}
#details.pw>.msg{margin:0 16px 12px}
#.copy{display:flex;gap:6px;margin:0 16px 10px}
#.copy input{flex:1;min-width:0;direction:ltr;font-size:12px;padding:9px 10px}
#.dns>.copy{margin:0 0 10px}
#form.codebox{display:flex;gap:6px;margin:0 0 10px}
#form.codebox input{flex:1;min-width:0;padding:9px 10px}
#form.codebox button{width:auto;margin:0;padding:9px 16px}
#.dns>label{margin-top:10px}
#table.moves{width:calc(100% - 32px);margin:0 16px 14px;border-collapse:collapse;
# font-size:12px}
#table.moves td{padding:7px 4px;border-bottom:1px solid var(--row);vertical-align:top}
#table.moves td small{display:block;color:var(--muted)}
#table.moves td:first-child,table.moves td:last-child{white-space:nowrap}
#table.moves td:first-child{direction:ltr;text-align:right;color:var(--muted)}
#table.moves td:last-child{text-align:left}
#.copy button{width:auto;padding:8px 14px;margin:0;font-size:12px;flex:none}
#button.small{width:auto;padding:6px 12px;margin:0;font-size:12px}
#.ok{color:var(--accent)}.bad{color:var(--bad)}.warn{color:var(--warn)}
#.shell{width:100%;max-width:440px}
#.shell:has(.usage){max-width:600px}
#h2{font-size:14px;font-weight:600;margin:26px 0 8px}
#.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;
