#[Unit]
#Description=Smart DNS over HTTPS and TLS - the relay's encrypted door
#After=network-online.target dnsmasq.service
#Wants=network-online.target
#
#[Service]
#Type=simple
#ExecStart=/usr/local/bin/smartdns-doh
#Restart=always
#RestartSec=3
## Root only to wake the sync agent with a signal when a new device turns up;
## it listens on loopback and nginx is the only thing that reaches it.
#NoNewPrivileges=yes
#ProtectHome=yes
#PrivateTmp=yes
#
#[Install]
#WantedBy=multi-user.target
#__END_DOH_SERVICE__

#__BEGIN_DNS_PROFILE_UNIT__
#[Unit]
#Description=Smart DNS resolver for service template %i
#After=network-online.target
#PartOf=smartdns-sync.service
#
#[Service]
#Type=simple
## /etc/smartdns-base mirrors /etc/dnsmasq.d by symlink, minus the operator's
## custom domains. Sharing by symlink means `smartdns add` and epic-pin still
## reach every resolver; leaving the custom file out is what lets a template
## not route those domains, since they cannot be un-routed by rule.
#ExecStart=/usr/sbin/dnsmasq --keep-in-foreground --conf-file=/dev/null \
#    --conf-dir=/etc/smartdns-base --conf-file=/etc/smartdns-profiles/%i.conf
#Restart=always
#RestartSec=5
#
#[Install]
#WantedBy=multi-user.target
#__END_DNS_PROFILE_UNIT__

#__BEGIN_DNS_GATE_UNIT__
#[Unit]
#Description=Smart DNS: the service's own names for addresses not registered yet
#After=network-online.target
#PartOf=smartdns-sync.service
#
#[Service]
#Type=simple
## Its own file only - not /etc/dnsmasq.d, not the templates' shared rules: an
## address that has not registered gets the customer panel's name and nothing
## else, so it can reach the page that registers it.
#ExecStart=/usr/sbin/dnsmasq --keep-in-foreground --conf-file=/etc/smartdns-profiles/gate.conf
#Restart=always
#RestartSec=5
#
#[Install]
#WantedBy=multi-user.target
#__END_DNS_GATE_UNIT__

